/**
 * Example sentences, classifiers and usage notes, written out by hand.
 *
 * Most of the deck arrived with a gloss and nothing else: no example, no
 * classifier, and — where a note existed — Thai words printed with no reading
 * beside them, which for someone still learning the script is a note that
 * cannot be read at all.
 *
 * Written here rather than generated because it is read every day and only
 * written once. Three rules it has to keep, and the tests enforce all three:
 *
 *  1. Every Thai word in a note or a classifier carries its reading in
 *     slashes — ตัว /tuːa/ — because a bracket after a Thai word reads as its
 *     meaning, which is how the old notes ended up unreadable.
 *  2. Every example has all three parts: Thai, reading, English. Two out of
 *     three is a card you cannot use.
 *  3. A classifier is set only where one is actually used. Thai nouns take
 *     them; verbs and adjectives do not, and filling the field in anyway
 *     would teach something false.
 */

export interface Revision {
  thai: string
  /** Defaults to 'word'. Set for sentences, which are matched separately. */
  kind?: 'word' | 'phrase'
  exampleThai: string
  exampleIpa: string
  exampleEnglish: string
  /** The counter this noun takes, with its reading. Null for anything else. */
  classifier?: string | null
  /** What a gloss leaves out: register, a near-synonym, a trap. */
  context?: string | null
}

/** Bumped when this set is rewritten, so the app applies it again. */
